using System;
using Grasshopper.Kernel;

namespace BenchPlugin
{
    public class RemapComponent : GH_Component
    {
        public RemapComponent()
            : base("Remap", "Remap", "Remaps a number from a source range to a target range", "Bench", "Math")
        {
        }

        public override Guid ComponentGuid => new Guid("b1e4a6c2-95d3-4f07-a8b1-3d7c2e6f1a02");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddNumberParameter("Value", "V", "Value to remap", GH_ParamAccess.item, 0.0);
            pManager.AddNumberParameter("Source Min", "S0", "Source range minimum", GH_ParamAccess.item, 0.0);
            pManager.AddNumberParameter("Source Max", "S1", "Source range maximum", GH_ParamAccess.item, 1.0);
            pManager.AddNumberParameter("Target Min", "T0", "Target range minimum", GH_ParamAccess.item, 0.0);
            pManager.AddNumberParameter("Target Max", "T1", "Target range maximum", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Result", "R", "Remapped value", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            double v = 0, s0 = 0, s1 = 1, t0 = 0, t1 = 1;
            if (!DA.GetData(0, ref v)) return;
            if (!DA.GetData(1, ref s0)) return;
            if (!DA.GetData(2, ref s1)) return;
            if (!DA.GetData(3, ref t0)) return;
            if (!DA.GetData(4, ref t1)) return;
            if (s0 == s1)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Source range has zero width");
                return;
            }
            DA.SetData(0, t0 + (v - s0) / (s1 - s0) * (t1 - t0));
        }
    }
}
