using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Grasshopper.Kernel;

namespace BenchPlugin
{
    public class AsyncStatsComponent : GH_Component
    {
        private CancellationTokenSource _cts;
        private Task<(double Mean, double StdDev)> _task;
        private List<double> _lastInput;
        private (double Mean, double StdDev)? _result;

        public AsyncStatsComponent()
            : base("Async Stats", "AsyncStats", "Computes mean and standard deviation asynchronously", "Bench", "Data")
        {
        }

        public override Guid ComponentGuid => new Guid("f5c8eaa6-d917-4d4b-8cf5-7b106cad5e46");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddNumberParameter("Values", "V", "Numbers to analyse", GH_ParamAccess.list);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Mean", "M", "Arithmetic mean", GH_ParamAccess.item);
            pManager.AddNumberParameter("StdDev", "SD", "Population standard deviation", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var values = new List<double>();
            if (!DA.GetDataList(0, values) || values.Count == 0)
            {
                Cancel();
                _lastInput = null;
                _result = null;
                return;
            }

            bool changed = _lastInput == null || !_lastInput.SequenceEqual(values);
            if (changed)
            {
                Cancel();
                _lastInput = values;
                _result = null;

                var cts = new CancellationTokenSource();
                _cts = cts;
                var token = cts.Token;
                var data = values.ToArray();
                _task = Task.Run(() => Compute(data, token), token);
                _task.ContinueWith(t =>
                {
                    if (t.IsCanceled || t.IsFaulted || token.IsCancellationRequested) return;
                    _result = t.Result;
                    var doc = OnPingDocument();
                    if (doc == null) return;
                    doc.ScheduleSolution(5, d => ExpireSolution(false));
                }, TaskScheduler.Default);
            }

            if (_result.HasValue)
            {
                DA.SetData(0, _result.Value.Mean);
                DA.SetData(1, _result.Value.StdDev);
            }
            else
            {
                Message = "Computing...";
            }
        }

        public override void RemovedFromDocument(GH_Document document)
        {
            Cancel();
            base.RemovedFromDocument(document);
        }

        private void Cancel()
        {
            _cts?.Cancel();
            _cts = null;
            _task = null;
            Message = string.Empty;
        }

        private static (double Mean, double StdDev) Compute(double[] data, CancellationToken token)
        {
            double sum = 0;
            for (int i = 0; i < data.Length; i++)
            {
                token.ThrowIfCancellationRequested();
                sum += data[i];
            }
            double mean = sum / data.Length;
            double sq = 0;
            for (int i = 0; i < data.Length; i++)
            {
                token.ThrowIfCancellationRequested();
                sq += (data[i] - mean) * (data[i] - mean);
            }
            return (mean, Math.Sqrt(sq / data.Length));
        }
    }
}
